package studio.jiayu.matrix;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
/** A native, user-started player. Simulation is explicitly distinct from physical delivery. */
public final class MatrixService extends Service {
 static volatile boolean alive;long renewAt;
 static final String CHANNEL="neo-matrix";static final int NOTIFY=391;
 ScheduledExecutorService worker;MatrixConnection connection;MatrixDevice device;JSONObject spec;int frame;long sent;boolean simulation,finished,keepLit;volatile boolean stopping;PowerManager.WakeLock wake;
 public static String status(Context c){String s=c.getSharedPreferences("matrix-status",0).getString("value","{\"state\":\"stopped\",\"message\":\"未启动\"}");try{JSONObject o=new JSONObject(s);if(!alive&&(o.optString("state").equals("running")||o.optString("state").equals("starting")))return o.put("state","interrupted").put("message","上次播放已结束，请重新启动").toString();}catch(Exception ignored){}return s;}
 public static void start(Activity a,String text,boolean simulate)throws Exception{start(a,text,simulate,true);}
 public static void start(Activity a,String text,boolean simulate,boolean keepLit)throws Exception{MatrixSpec.parse(text);if(alive)throw new Exception("请先停止当前播放，再开始新的动画");if(!simulate&&!MatrixDevice.available(a)&&!MatrixConnection.configured(a))throw new Exception("尚未配置当前 App 的官方背屏授权。可先使用后台模拟验证动画。");if(a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0&&Build.VERSION.SDK_INT>=33)throw new Exception("请先点“通知与后台权限”，允许显示播放通知");File target=new File(a.getFilesDir(),"matrix-play.json");try(FileOutputStream o=new FileOutputStream(target)){o.write(text.getBytes("UTF-8"));}a.startForegroundService(new Intent(a,MatrixService.class).putExtra("simulate",simulate).putExtra("keepLit",keepLit));}
 void state(String s,String message){try{getSharedPreferences("matrix-status",0).edit().putString("value",new JSONObject().put("state",s).put("message",message).put("simulation",simulation).put("keepLit",keepLit).put("transport",simulation?"simulation":device!=null?"neo-native":"official-mcp").put("frame",frame).put("sent",sent).put("time",System.currentTimeMillis()).toString()).apply();}catch(Exception ignored){}}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i==null||"stop".equals(i.getAction())){stopPlayback();return START_NOT_STICKY;}if(worker!=null){state("running","正在播放；先停止再切换动画");return START_NOT_STICKY;}alive=true;simulation=i.getBooleanExtra("simulate",false);keepLit=i.getBooleanExtra("keepLit",true);
  NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"背屏动画播放",NotificationManager.IMPORTANCE_LOW));Intent open=getPackageManager().getLaunchIntentForPackage(getPackageName());PendingIntent content=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,MatrixService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
  Notification n=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(simulation?"点阵后台模拟 · 不驱动背屏":"StepX Neo 背屏播放").setContentText("点击返回 · 可随时停止").setContentIntent(content).setOngoing(true).addAction(new Notification.Action.Builder(null,"停止",stop).build()).build();if(Build.VERSION.SDK_INT>=34)startForeground(NOTIFY,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(NOTIFY,n);
  worker=Executors.newSingleThreadScheduledExecutor();connection=new MatrixConnection(this);state("starting","正在启动");worker.execute(()->{try{try(InputStream in=new FileInputStream(new File(getFilesDir(),"matrix-play.json"));ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[4096];int k;while((k=in.read(b))!=-1){if(o.size()+k>350000)throw new Exception("点阵文件过大");o.write(b,0,k);}spec=MatrixSpec.parse(o.toString("UTF-8"));}if(!simulation&&MatrixDevice.available(this)){device=new MatrixDevice(this);device.prepare(keepLit);}wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,getPackageName()+":matrix");wake.setReferenceCounted(false);wake.acquire(10*60*1000L);renewAt=SystemClock.elapsedRealtime()+5*60*1000L;tick();}catch(Exception e){fail(e);}});return START_NOT_STICKY;
 }
 void tick(){if(stopping)return;if(wake!=null&&SystemClock.elapsedRealtime()>=renewAt){wake.acquire(10*60*1000L);renewAt=SystemClock.elapsedRealtime()+5*60*1000L;}try{JSONArray frames=spec.getJSONArray("frames");JSONObject f=frames.getJSONObject(frame);if(!simulation){if(device!=null)device.frame(f.getJSONArray("pixels"));else connection.call("set_back_screen_frame",new JSONObject().put("frame",f.getJSONArray("pixels")));}if(stopping)return;sent++;state("running",simulation?"后台模拟中，未发送到背屏":(device!=null&&keepLit?"背屏常亮播放中":"已提交背屏帧；实际显示受系统背屏开关和显示策略控制"));int delay=f.getInt("durationMs");frame++;if(frame>=frames.length()){if(spec.getBoolean("loop"))frame=0;else{worker.schedule(()->stopPlayback(),delay,TimeUnit.MILLISECONDS);return;}}worker.schedule(this::tick,delay,TimeUnit.MILLISECONDS);}catch(Exception e){if(!stopping)fail(e);}}
 void fail(Exception e){finished=true;state("error",e.getMessage()==null?"背屏播放失败":e.getMessage());stopSelf();}
 void stopPlayback(){if(stopping)return;stopping=true;if(connection!=null)connection.cancel();if(worker==null){state("stopped","已停止");finished=true;stopSelf();return;}worker.execute(()->{String message="已停止";if(!simulation&&sent>0)try{if(device!=null)device.clear();else connection.call("clear_back_screen_frame",new JSONObject());}catch(Exception e){message="播放已停止；清屏失败，请在官方背屏设置恢复";}state("stopped",message);finished=true;stopSelf();});}
 @Override public void onDestroy(){alive=false;stopping=true;if(connection!=null)connection.cancel();if(worker!=null)worker.shutdownNow();if(wake!=null&&wake.isHeld())wake.release();if(device!=null)try{device.restore();}catch(Exception e){state("error","播放已停止，背屏设置恢复失败；请在系统设置恢复显示模式");finished=true;}if(!finished)state("stopped",simulation?"后台模拟已结束":"服务已结束；如有残留画面请在官方背屏设置恢复");stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
